// Typed API contracts — mirrors backend/contracts/openapi.json exactly.
//
// Source of truth: backend/contracts/openapi.json (OpenAPI 3.1, app v0.4.0).
// Generated by hand from the committed schema; the
// `npm run openapi:check` script re-verifies the schemas match at build
// time so drift is caught.
//
// Naming: TypeScript interfaces use the same names as the OpenAPI
// component schemas (UserResponse, LoginRequest, etc.). Enum-like unions
// are spelled exactly as the backend's Literal/enum values.
//
// IMPORTANT: the session token is NEVER in any response body. It lives
// only in the HttpOnly cookie set by POST /auth/login. No field for it
// exists here, by design.

// --- Shared -------------------------------------------------------------

/** Request-ID response header (also echoed in ErrorEnvelope.error.request_id). */
export const REQUEST_ID_HEADER = "X-Request-ID" as const;

/** CSRF request header (echo of the cookie value on state-changing writes). */
export const CSRF_HEADER = "X-CSRF-Token" as const;

/** Cookie name for the readable CSRF value (double-submit). */
export const CSRF_COOKIE_NAME = "peiars_csrf" as const;

/** Cookie name for the HttpOnly session token (never read by JS). */
export const SESSION_COOKIE_NAME = "peiars_session" as const;

// --- Errors -------------------------------------------------------------

/** Stable machine-readable error codes (subset used by the frontend). */
export type ErrorCode =
  | "VALIDATION_ERROR"
  | "BAD_REQUEST"
  | "NOT_FOUND"
  | "METHOD_NOT_ALLOWED"
  | "INVALID_SOURCE_ID"
  | "SOURCE_NOT_FOUND"
  | "SERVICE_NOT_READY"
  | "INTERNAL_SERVER_ERROR"
  | "REQUEST_FAILED"
  | "CONFLICT"
  | "CASE_NOT_FOUND"
  | "INVALID_TRANSITION"
  | "UNAUTHORIZED"
  | "FORBIDDEN"
  | "RATE_LIMITED"
  | "CSRF_TOKEN_INVALID";

export interface ErrorBody {
  /** Stable machine-readable error code. */
  code: ErrorCode | string;
  /** Human-readable, sanitized error message. */
  message: string;
  /** Request ID for cross-referencing server logs. */
  request_id: string;
  /** Optional structured details (sanitized; never a raw traceback). */
  details?: Record<string, unknown>;
}

export interface ErrorEnvelope {
  error: ErrorBody;
}

// --- Health -------------------------------------------------------------

export interface HealthLiveResponse {
  status: "alive";
  service: string;
  version: string;
}

export interface ReadinessCheck {
  name: string;
  status: "ready" | "unavailable";
}

export interface ReadinessResponse {
  status: "ready";
  checks: ReadinessCheck[];
}

// --- Meta ---------------------------------------------------------------

export type FeatureState = "implemented" | "planned";
export type SubsystemState = "available" | "empty" | "not_integrated";

export interface MetaResponse {
  application: string;
  api_version: "v1";
  app_version: string;
  git_commit_sha: string | null;
  environment: "development" | "test" | "production";
  features: Record<string, FeatureState>;
  subsystems: Record<string, SubsystemState>;
}

// --- Sources ------------------------------------------------------------

export type DatasetKind =
  | "ulb_benchmark"
  | "pmgsy_infrastructure"
  | "mplads_administration";

export type IntegrityStatus =
  | "verified"
  | "unverified_legacy"
  | "integrity_failed"
  | "unavailable";

export type AnalysisStatus =
  | "verified_benchmark"
  | "exploratory"
  | "restricted"
  | "blocked"
  | "unavailable";

export interface SourceSummary {
  source_id: string;
  dataset_kind: DatasetKind;
  integrity_status: IntegrityStatus;
  analysis_status: AnalysisStatus;
}

export interface SourceListResponse {
  sources: SourceSummary[];
  count: number;
}

// --- Auth ---------------------------------------------------------------

export type Role = "viewer" | "reviewer" | "admin";

export interface LoginRequest {
  username: string; // 3–64 chars
  password: string; // 8–128 chars
}

export interface UserResponse {
  id: string;
  username: string;
  display_name: string;
  role: Role;
  permissions: string[];
}

export interface LogoutResponse {
  status: "logged_out";
}

export interface CsrfTokenResponse {
  csrf_token: string;
}

// --- Synthetic demonstration records (PR-05B) ---------------------------

export interface SyntheticRecordSummary {
  record_ref: string;
  title: string;
  dataset_id: string;
  snapshot_id: string;
  synthetic: boolean;
}

export interface SyntheticRecordDetail {
  record_ref: string;
  title: string;
  description: string;
  evidence_summary: string;
  administrative_context: string;
  limitations: string;
  dataset_id: string;
  snapshot_id: string;
  synthetic: boolean;
}

export interface SyntheticRecordListResponse {
  items: SyntheticRecordSummary[];
  total: number;
  dataset_id: string;
  snapshot_id: string;
}

// --- Review cases (PR-05B) ----------------------------------------------

export type ReviewStatus =
  | "not_reviewed"
  | "under_review"
  | "explained_deviation"
  | "needs_source_verification"
  | "escalated_for_examination";

export type CaseEventType =
  | "created"
  | "note_added"
  | "status_changed"
  | "decision_recorded"
  | "reopened";

/** Alias matching the OpenAPI schema name (EventType). */
export type EventType = CaseEventType;

export interface CreateCaseRequest {
  dataset_id: string;
  snapshot_id: string;
  record_ref: string;
  title: string;
  summary?: string | null;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  created_by: string;
}

export interface CaseSummary {
  id: string;
  dataset_id: string;
  snapshot_id: string;
  record_ref: string;
  status: ReviewStatus;
  title: string;
  summary?: string | null;
  created_at: string;
  updated_at: string;
  version: number;
  created_by: string;
}

export type CaseDetail = CaseSummary;

export interface CaseListResponse {
  items: CaseSummary[];
  total: number;
  limit: number;
  offset: number;
}

export interface AddNoteRequest {
  note_text: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface TransitionStatusRequest {
  to_status: ReviewStatus;
  reason: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface RecordDecisionRequest {
  outcome: ReviewStatus;
  rationale: string;
  /** Ignored by the server — actor is derived from the authenticated principal. */
  actor_ref: string;
  expected_version: number;
}

export interface CaseEventRecord {
  id: string;
  case_id: string;
  event_type: CaseEventType;
  event_at: string;
  actor_ref: string;
  previous_status?: ReviewStatus | null;
  new_status?: ReviewStatus | null;
  reason?: string | null;
  event_payload?: Record<string, unknown> | null;
  case_version: number;
  event_seq: number;
}

export interface CaseHistoryResponse {
  case_id: string;
  items: CaseEventRecord[];
  total: number;
}

// --- Research (PR-08: read-only frozen scientific results) --------------

export interface ResearchSourceSummary {
  source_id: string;
  dataset_id: string;
  research_family: string;
  model_methods: string[];
  result_type: string;
  result_granularity: string;
  availability: string;
}

export interface ResearchSourceListResponse {
  items: ResearchSourceSummary[];
  count: number;
}

export interface ResearchSourceDetail extends ResearchSourceSummary {
  artifact_path: string;
  artifact_sha256: string;
  digest_algorithm: string;
  canonicalization: string;
  experimental_context: Record<string, unknown>;
  limitations: string[];
}

export interface ResearchResultItem {
  metric_name: string;
  value: number | string;
  value_type: "int" | "float" | "str";
  description: string;
}

export interface ResearchProvenance {
  artifact_path: string;
  artifact_sha256: string;
  digest_algorithm: string;
  canonicalization: string;
}

export interface ResearchResultsResponse {
  source_id: string;
  dataset_id: string;
  model_methods: string[];
  results: ResearchResultItem[];
  interpretation_principles: string[];
  exploratory_caveat: string;
  provenance: ResearchProvenance;
  limitations: string[];
  is_precomputed: true;
  is_live_prediction: false;
}
